import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionId = req.getHeader("X-Session-Id");
        if (sessionId == null || sessionId.length() < 16) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String sortDir = req.getParameter("dir");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Build report query - parameterized for values but dynamic ORDER BY
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT e.name, e.employee_id, d.dept_name, r.hours_worked, r.report_date ");
        sql.append("FROM reports r JOIN employees e ON r.emp_id = e.id ");
        sql.append("JOIN departments d ON e.dept_id = d.id ");
        sql.append("WHERE r.report_date BETWEEN ? AND ? ");
        sql.append("AND r.report_type = ? ");

        if (department != null && !department.isEmpty()) {
            sql.append("AND d.dept_name = ? ");
        }

        // ORDER BY cannot be parameterized in JDBC
        if (sortCol != null) {
            sql.append("ORDER BY ").append(sortCol);
            if (sortDir != null && sortDir.equalsIgnoreCase("DESC")) {
                sql.append(" DESC");
            } else {
                sql.append(" ASC");
            }
        } else {
            sql.append("ORDER BY r.report_date ASC");
        }

        log.info("Report query for type=" + reportType + " dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            stmt.setString(1, startDate);
            stmt.setString(2, endDate);
            stmt.setString(3, reportType);
            if (department != null && !department.isEmpty()) {
                stmt.setString(4, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"name\":\"%s\",\"id\":\"%s\",\"dept\":\"%s\",\"hours\":%.1f,\"date\":\"%s\"}",
                    rs.getString(1), rs.getString(2), rs.getString(3),
                    rs.getDouble(4), rs.getString(5));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
